\begin{document}
\title{Spontaneous Quantum Turbulence in a Newborn Bose-Einstein Condensate via the Kibble-Zurek Mechanism}

\author{Seong-Ho Shinn\orcidlink{0000-0002-2041-5292}}
\email{seongho.shin@uni.lu}
\affiliation{Department of Physics and Materials Science, University of Luxembourg, L-1511 Luxembourg, Luxembourg}

