  \includegraphics[width=0.42\linewidth]{Enstrophy_time_evol_Tq_30_T_1_v2.pdf}
  \qquad
  \includegraphics[width=0.42\linewidth]{Enstrophy_time_evol_Tq_350_T_1_v4.pdf}
  \caption{Number of vortices $n_v \left( t \right)$ and enstrophy $\Omega_u \left( t \right) = \int \left\vert \nabla \times \boldsymbol{u} \left( \boldsymbol{r}, t \right) \right\vert^2 \; d^2 \boldsymbol{r}$ as functions of time $t$. The data are from the same $T=1$ simulations as in Fig. \ref{fig:E_i(k)_time_evolution_Tq_30_350}, with quench times (a) $\tau_Q=30$ ($t_{\textrm{eq}}=25.9$) and (b) $\tau_Q=350$ ($t_{\textrm{eq}}=111.5$).
}
  \label{fig:enstrophy_vs_time}
\end{figure}
Besides the energy spectrum, we have also examined the time evolution of the enstrophy, defined as
\begin{equation}
\Omega_u(t) = \int \left| \nabla \times \boldsymbol{u}(\boldsymbol{r}, t) \right|^2 \, d^2\boldsymbol{r},
\end{equation}
where $\nabla \times \boldsymbol{u}$ denotes the vorticity associated with the weighted superfluid velocity field
(we considered the curl of the weighted velocity $\boldsymbol{u}$, since the integration of the curl of the velocity is proportional to the number of vortices).
In two-dimensional (2D) classical turbulence, the conservation of enstrophy plays a key role, as it leads to an inverse energy cascade characterized by the formation of increasingly larger eddies.
In quantum turbulence (QT), a similar mechanism can occur through the clustering of same-sign vortices, resulting in extended regions of high vorticity. However, in 2D
QT,
enstrophy is not necessarily conserved, and this can give rise to a direct energy cascade \cite{Numasato2010,Chesler13,Zhao25}.
Fig.
\ref{fig:enstrophy_vs_time} shows the time evolution of the enstrophy together with the vortex count from the same data used in Fig. \ref{fig:E_i(k)_time_evolution_Tq_30_350}, for $\tau_{Q}=30$ in panel (a) and $\tau_{Q}=350$ in (b). The results indicate that enstrophy is not conserved throughout the evolution, suggesting the presence of a direct energy cascade. Moreover, tracking the vortex positions over time reveals
no formation of same-sign vortex clusters.

\section{Numerical evaluation of the compressible and incompressible energy spectra}
Given the weighted superfluid velocity $\boldsymbol{u}$, we outline the procedure to extract its irrotational and solenoidal components, $\boldsymbol{u}_{c}$ and $\boldsymbol{u}_{i}$, respectively.

Using the Green's function \cite{Watanabe2013}, any
two-dimensional vector field $\boldsymbol{V} \left( \boldsymbol{r}\right)$ can be expressed as
\begin{equation}\label{vector_integral_identity}
\boldsymbol{V} \left( \boldsymbol{r}\right)
=
\int
\boldsymbol{V} \left( \boldsymbol{r}^{\prime}\right)
\delta \left( \boldsymbol{r} - \boldsymbol{r}^{\prime} \right)
\, d^2 \boldsymbol{r}^{\prime}
=
\nabla^2
\left\lbrack
\frac{1}{2 \pi}
\int
\boldsymbol{V} \left( \boldsymbol{r}^{\prime}\right)
\ln \left( \frac{\left\vert \boldsymbol{r} - \boldsymbol{r}^{\prime} \right\vert}{l} \right)
\,
d^2 \boldsymbol{r}^{\prime}
\right\rbrack
,
\end{equation}
where $\delta \left( \boldsymbol{r} \right)$ is the two-dimensional Dirac delta function
and $l$ is a constant with units of length.
Applying Eq. (\ref{vector_integral_identity}) to $\boldsymbol{u}(\boldsymbol{r})$ yields $\boldsymbol{u}(\boldsymbol{r})=\nabla^{2}\boldsymbol{b}(\boldsymbol{r})$, where $
\boldsymbol{b} \left( \boldsymbol{r}\right)
\coloneqq
\left( 1 / 2 \pi \right)
\int
\boldsymbol{u} \left( \boldsymbol{r}^{\prime} \right)
\ln \left( \left\vert \boldsymbol{r} - \boldsymbol{r}^{\prime} \right\vert / l \right)
\, d^2 \boldsymbol{r}^{\prime}
$.
Using the vector identity $\nabla \times \left( \nabla \times \boldsymbol{A} \right) = \nabla \left( \nabla \cdot \boldsymbol{A} \right) - \nabla^2 \boldsymbol{A}$, we can thus decompose $\boldsymbol{u}$ into:
\begin{equation}
\boldsymbol{u}_{c} \left( \boldsymbol{r}, t \right)
=
\nabla
\left\lbrack
\nabla
\cdot
\boldsymbol{b} \left( \boldsymbol{r}, t \right)
\right\rbrack
, \quad
\boldsymbol{u}_{i} \left( \boldsymbol{r}, t \right)
=
-
\nabla
\times
\left\lbrack
\nabla
\times
\boldsymbol{b} \left( \boldsymbol{r}, t \right)
\right\rbrack,
\label{Eq:app:B:vc_vic_as_b}
\end{equation}
satisfying
$\nabla \times \boldsymbol{u}_{c} \left( \boldsymbol{r}, t \right) = 0$ and
$\nabla \cdot \boldsymbol{u}_{i} \left( \boldsymbol{r}, t \right) = 0$.

In Fourier space, we have $\boldsymbol{\tilde{u}}(\boldsymbol{k})=-{k}^{2}\boldsymbol{\tilde{b}}(\boldsymbol{k})$, with $\boldsymbol{\tilde{b}} \left( \boldsymbol{k}, t \right)
=
\left( 1 / 2 \pi \right)
\int
e^{- i \boldsymbol{k} \cdot \boldsymbol{r}}
\boldsymbol{b} \left( \boldsymbol{r}, t \right)
\, d^2 \boldsymbol{r} $.
Inserting this into Eq. (\ref{Eq:app:B:vc_vic_as_b}) gives:
\begin{equation}\label{u_c_and_u_i_expressed_as_k_integrals}
\boldsymbol{u}_{c} \left( \boldsymbol{r}, t \right)
=
\frac{1}{2 \pi}
\int
\frac{\boldsymbol{k}}{k^2}
\left\lbrack
\boldsymbol{k}
\cdot
\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right)
\right\rbrack
e^{i \boldsymbol{k} \cdot \boldsymbol{r}}
\, d^2 \boldsymbol{k}
, \quad
\boldsymbol{u}_{i} \left( \boldsymbol{r}, t \right)
=
-
\frac{1}{2 \pi}
\int
\frac{\boldsymbol{k}}{k^2}
\times
\left\lbrack
\boldsymbol{k}
\times
\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right)
\right\rbrack
e^{i \boldsymbol{k} \cdot \boldsymbol{r}}
\, d^2 \boldsymbol{k}
,
\end{equation}
where $k \coloneqq \left\vert \boldsymbol{k} \right\vert$.
Thus, in momentum space, the compressible and incompressible components of $\boldsymbol{u}$ read
$
\boldsymbol{\tilde{u}}_{c} \left( \boldsymbol{k}, t \right)
=
\boldsymbol{e}_k
\left\lbrack
\boldsymbol{e}_k
\cdot
\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right)
\right\rbrack
$, and
$
\boldsymbol{\tilde{u}}_{i} \left( \boldsymbol{k}, t \right)
=
\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right)
-
\boldsymbol{\tilde{u}}_{c} \left( \boldsymbol{k}, t \right)
$ where $\boldsymbol{e}_k \coloneqq \boldsymbol{k} / k$.
Finally, the compressible and incompressible energy spectra are given by
\begin{equation}\label{E_c_k_and_E_i_k_equations}
E_{c} \left( k
, t
\right)
=
\frac{k}{2}
\int_{0}^{2 \pi}
\left\lbrack
\boldsymbol{e}_k
\cdot
\boldsymbol{\tilde{u}}^{*} \left( \boldsymbol{k}, t \right)
\right\rbrack
\left\lbrack
\boldsymbol{e}_k
\cdot
\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right)
\right\rbrack
\, d \varphi_k
, \quad
E_{i} \left( k
, t
\right)
=
\frac{k}{2}
\int_{0}^{2 \pi}
\boldsymbol{\tilde{u}}^{*} \left( \boldsymbol{k}, t \right)
\cdot
\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right)
\, d \varphi_k
-
E_{c} \left( k \right)
,
\end{equation}
where $\varphi_k$ is the azimuthal angle of $\boldsymbol{k}$, i.e., $\boldsymbol{e}_k = \left( \cos \varphi_k, \sin \varphi_k \right)$.
As our analysis mainly focuses on the system at equilibration time $t_{\textrm{eq}}$, we will omit the time argument for brevity and denote $E_{c, i}(k) \coloneqq E_{c, i}(k, t_{\textrm{eq}})$.

\begin{figure}[hptb]
\centering
\includegraphics[width=0.8 \linewidth]{Ec_Eic_quadrature_v3.pdf}
\caption{
\textbf{Kinetic energy spectrum calculated using the quadrature
method}.
(a) Compressible kinetic energy spectrum $E_c(k)$ as a function of $k$ for different grid sizes $N_g$.
(b) Incompressible kinetic energy spectrum $E_i(k)$ as a function of $k$ for the same $N_g$.
Both panels correspond to a quench time of $\tau_Q = 60$, evaluated at the equilibration time.
For this analysis, a single realization was selected from the $1000$ independent noise realizations to determine the optimal $N_g$.
Each $N_g$ is chosen according to $N_g = 2 \lfloor L k_m / 2 \pi \rceil + 1$, with $k_m = 100$, $200$, $400$, and $600$.
}
\label{fig:Ec_Eic_quadrature}
\end{figure}

To numerically evaluate $E_{c,i}(k)$ as given in
Eqs. (\ref{E_c_k_and_E_i_k_equations}),
we used the Julia package \texttt{FFTW.jl}, which provides an interface to the \texttt{FFTW3} library \cite{FFTW05}, allowing efficient computation of the fast Fourier transform to obtain  $\boldsymbol{\tilde{u}} \left( \boldsymbol{k}\right)$.
To perform the angular integral over $\varphi_k$, we employed the quadrature method introduced in \cite{blakie2008dynamics}.
Denoting by $k_m$ the maximum wavenumber considered for evaluating
$E_{c,i}(k)$,
and by $N_g$ the number of grid points along each spatial direction for a periodic system of size $L \times L$, we compute and plot $E_c(k)$ and $E_i(k)$ for different values of $N_g$ in Fig. \ref{fig:Ec_Eic_quadrature}.
It
clearly shows that sufficiently large values of $N_g$ are required to suppress numerical errors at high wavenumbers $k$. We found that the minimal grid size needed to ensure accuracy for $k \leq k_m$ is approximately $N_g \approx 8 \lfloor L k_m / 2 \pi \rceil + 1$, where $\lfloor x \rceil$ denotes the nearest integer to $x$. Accordingly, we used $N_g = 3817$ to accurately compute
$E_{c,i}(k)$
up to $k \leq 100$.

\section{Numerical evaluation of the velocity structure function}
To numerically calculate the velocity structure function
\begin{equation}
S_p \left( r \right)
\coloneqq
\frac{1}{2 \pi L^2}
\int_{0}^{2 \pi}
\int_{0}^{L}
\int_{0}^{L}
\left\vert
\left\lbrack
\boldsymbol{u}_i \left( \boldsymbol{R} + \boldsymbol{r} \right)
-
\boldsymbol{u}_i \left( \boldsymbol{R} \right)
\right\rbrack
\cdot
\boldsymbol{e}_r
\right\vert^p
\;
d R_x \;
d R_y \;
d \varphi
,
\label{supp:eq:Sp}
\end{equation}
where $\boldsymbol{e}_r \coloneqq \boldsymbol{r} / r = \left( \cos \varphi, \sin \varphi \right)$ is the unit vector along $\boldsymbol{r}$ \cite{Ciliberto1994,Frisch1995}, we compute the velocity increments using the discrete Fourier transform, implemented via the Julia package \texttt{FFTW.jl}.
Let $\nu_j \coloneqq \left( j - 1 \right) L_{\nu} / N_{\nu}$ for $1 \le j \le N_{\nu}$ with $\nu = x, y$. The weighted superfluid velocity $\boldsymbol{u} \left( x_j, y_l\right)$ can then be written as
\begin{equation}
\boldsymbol{u} \left( x_j, y_l \right)
=
\frac{1}{N_x N_y}
\sum_{n_x = 1}^{N_x}
\sum_{n_y = 1}^{N_y}
\boldsymbol{\tilde{u}}\left( n_x - 1, n_y - 1 \right)
e^{2 \pi i \left( n_x - 1 \right) \left( j - 1 \right) / N_x}
e^{2 \pi i \left( n_y - 1 \right) \left( l - 1 \right) / N_y}
,
\end{equation}
where we used $\boldsymbol{k} / 2 \pi = \left( \left( n_x - 1 \right) / L_x, \left( n_y - 1 \right) / L_y \right)$ in the discrete Fourier space.
Since $\boldsymbol{u} \left( x_j, y_l \right)$ is real, its derivatives must also be real.
Using the identity $\exp \left( 2 \pi i \left( n_{\nu} - 1 \right) \left( j - 1 \right) / N_{\nu} \right) = \exp \left( 2 \pi i \left( n_{\nu} - 1 - N_{\nu} \right) \left( j - 1 \right) / N_{\nu} \right)$ for any integers $1 \le n_{\nu} \le N_{\nu}$ and $1 \le j \le N_{\nu}$, in order to make $\boldsymbol{u}_i \left( x_j, y_l \right)$ real, one should use the following expression:
\begin{equation}
\boldsymbol{u}_i \left( x_j, y_l \right)
=
\frac{1}{N_x N_y}
\sum_{n_x = 1}^{N_x}
\sum_{n_y = 1}^{N_y}
\frac{
\boldsymbol{k} \left( n_x, n_y \right)
}{
k^2 \left( n_x, n_y \right)
}
\times
\left\lbrack
\boldsymbol{\tilde{u}}\left( n_x - 1, n_y - 1 \right)
\times
\boldsymbol{k} \left( n_x, n_y \right)
\right\rbrack
e^{2 \pi i \left( n_x - 1 \right) \left( j - 1 \right) / N_x}
e^{2 \pi i \left( n_y - 1 \right) \left( l - 1 \right) / N_y}
,
\label{eq:app:u_i_discrete_space}
\end{equation}
with $\boldsymbol{k} \left( n_x, n_y \right) \coloneqq \sum_{\nu = x, y} k_{\nu} \left( n_x, n_y \right) \boldsymbol{e}_{\nu} $ and
\begin{equation}
k_{\nu} \left( n_x, n_y \right)
\coloneqq
\left\{
\begin{array}{cc}
2 \pi i \left( n_{\nu} - 1 \right) / L_{\nu}
,
&
\textrm{ if \; $1 \le n_{\nu} \le \left\lbrack N_{\nu} / 2 \right\rbrack_r + 1$,}
\\
\\
2 \pi i \left( n_{\nu} - 1 - N_{\nu} \right) / L_{\nu}
,
&
\textrm{ otherwise,}
\end{array}
\right.
\end{equation}
where $\left\lbrack x \right\rbrack_r$ is the greatest integer less than or equal to $x$, so that $- 2 \pi i \left\lbrack N_{\nu} / 2 \right\rbrack_r / L_{\nu} \le k_{\nu} \left( n_x, n_y \right) \le 2 \pi i \left\lbrack N_{\nu} / 2 \right\rbrack_r / L_{\nu}$.

Note that, for any function $f \left( x, y \right)$ in the periodic system $f \left( x + L_x, y \right) = f \left( x, y + L_y \right) = f \left( x, y \right)$,
\begin{equation}
\frac{1}{L_x L_y}
\int_0^{L_x}
\int_0^{L_y}
f \left( x, y \right) \;
d y \;
d x
=
\frac{1}{N_x N_y}
\sum_{j = 1}^{N_x}
\sum_{l = 1}^{N_y}
f \left( x_j, y_l \right)
.
\label{eq:app:spatial_numerical_integration}
\end{equation}
After numerically calculating $\boldsymbol{u}_i \left( x_j, y_l \right)$ via Eq. \eqref{eq:app:u_i_discrete_space},
we calculate
$
\Delta \boldsymbol{u}_i \left( \boldsymbol{R}, \boldsymbol{r} \right)
\coloneqq
\boldsymbol{u}_i \left( \boldsymbol{R} + \boldsymbol{r} \right)
-
\boldsymbol{u}_i \left( \boldsymbol{R} \right)
$ and then calculate $S_p \left( r \right)$ numerically as
\begin{equation}
S_p \left( r \right)
=
\frac{1}{L^2}
\int_{0}^{L}
\int_{0}^{L}
\left\lbrack
\frac{1}{2 \pi}
\int_0^{2 \pi}
\left\vert
\Delta \boldsymbol{u}_i \left( \boldsymbol{R}, \boldsymbol{r} \right)
\cdot
\boldsymbol{e}_r
\right\vert^p \;
d \varphi
\right\rbrack \;
d R_x \;
d R_y
=
\frac{1}{N^2_x}
\sum_{j, l = 1}^{N_x}
\left\lbrack
\frac{1}{2 \pi}
\int_{0}^{2 \pi}
\left\vert
\Delta \boldsymbol{u}_i \left( X_j, Y_l, \boldsymbol{r} \right)
\cdot
\boldsymbol{e}_r
\right\vert^p \;
d \varphi
\right\rbrack
,
\end{equation}
with $X_j \coloneqq \left( j - 1 \right) L / N_x$ and $Y_l \coloneqq \left( l - 1 \right) L / N_x$.

